theorem ProbabilityTheory.iIndepFun.extracted_1.{u_2, u_1} {Ω : Type u_1} [inst : MeasureSpace Ω] {G : Type u_2}
  [hG : MeasurableSpace G] {Z₁ Z₂ Z₃ Z₄ : Ω → G} (h_indep : iIndepFun (fun _i => hG) ![Z₁, Z₂, Z₃, Z₄] ℙ)
  (hZ₁ : Measurable Z₁) (hZ₂ : Measurable Z₂) (hZ₃ : Measurable Z₃) (hZ₄ : Measurable Z₄) {phi : G → G → G}
  (hphi : Measurable (Function.uncurry phi)) (i : (i : Fin 3) × ProbabilityTheory.iIndepFun.κ i) :
  Measurable (((fun {x} => ![Z₁, Z₂, Z₃, Z₄]) ∘' ⇑ProbabilityTheory.iIndepFun.κ_equiv) i) := by
  rintro ⟨i, j⟩; fin_cases i <;> fin_cases j <;> assumption
